mod common;

use axum::http::{Method, StatusCode};
use axum_bookclub::app;
use common::send;
use serde_json::json;

async fn make_club(router: &axum::Router, max_members: Option<u32>) -> u64 {
    let (_, body) = send(
        router,
        Method::POST,
        "/api/clubs",
        Some(json!({"name": "C", "description": "x", "max_members": max_members})),
    )
    .await;
    body["id"].as_u64().unwrap()
}

#[tokio::test]
async fn member_creation_rejected_when_club_at_capacity() {
    let router = app();
    let club_id = make_club(&router, Some(1)).await;

    let (status1, _) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{club_id}/members"),
        Some(json!({"name": "Ada", "email": "a@example.com"})),
    )
    .await;
    assert_eq!(status1, StatusCode::CREATED);

    let (status2, _) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{club_id}/members"),
        Some(json!({"name": "Bob", "email": "b@example.com"})),
    )
    .await;
    assert_eq!(status2, StatusCode::BAD_REQUEST);
}

#[tokio::test]
async fn member_transfer_rejected_when_target_club_at_capacity() {
    let router = app();
    let full_club = make_club(&router, Some(1)).await;
    let other_club = make_club(&router, None).await;

    send(
        &router,
        Method::POST,
        &format!("/api/clubs/{full_club}/members"),
        Some(json!({"name": "Ada", "email": "a@example.com"})),
    )
    .await;
    let (_, other_member) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{other_club}/members"),
        Some(json!({"name": "Bob", "email": "b@example.com"})),
    )
    .await;
    let other_member_id = other_member["id"].as_u64().unwrap();

    let (status, _) = send(
        &router,
        Method::PATCH,
        &format!("/api/members/{other_member_id}"),
        Some(json!({"club_id": full_club})),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "transfer must respect the target club's cap too");
}

