use std::sync::Arc;

use axum::extract::{Path, State};
use axum::http::StatusCode;
use axum::response::IntoResponse;
use axum::Json;
use serde::Deserialize;
use serde_json::json;

use crate::state::{AppState, Member};

fn cap_exceeded(store: &crate::state::Store, club_id: u32) -> bool {
    match store.clubs.get(&club_id) {
        Some(club) => match club.max_members {
            Some(max) => store.member_count(club_id) >= max,
            None => false,
        },
        None => false,
    }
}

#[derive(Deserialize)]
pub struct CreateMember {
    pub name: Option<String>,
    pub email: Option<String>,
}

pub async fn create_member(
    State(state): State<Arc<AppState>>,
    Path(club_id): Path<u32>,
    Json(body): Json<CreateMember>,
) -> impl IntoResponse {
    let name = body.name.unwrap_or_default().trim().to_string();
    let email = body.email.unwrap_or_default().trim().to_string();
    if name.is_empty() {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "name is required"}))).into_response();
    }
    if email.is_empty() {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "email is required"}))).into_response();
    }

    let mut store = state.store.lock().unwrap();
    if !store.clubs.contains_key(&club_id) {
        return (StatusCode::NOT_FOUND, Json(json!({"error": "club not found"}))).into_response();
    }
    if cap_exceeded(&store, club_id) {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "club is at max_members capacity"}))).into_response();
    }
    let id = store.next_member_id;
    store.next_member_id += 1;
    let member = Member { id, club_id, name, email };
    store.members.insert(id, member.clone());
    (StatusCode::CREATED, Json(member)).into_response()
}

pub async fn list_members(
    State(state): State<Arc<AppState>>,
    Path(club_id): Path<u32>,
) -> impl IntoResponse {
    let store = state.store.lock().unwrap();
    if !store.clubs.contains_key(&club_id) {
        return (StatusCode::NOT_FOUND, Json(json!({"error": "club not found"}))).into_response();
    }
    let mut members: Vec<Member> = store
        .members
        .values()
        .filter(|m| m.club_id == club_id)
        .cloned()
        .collect();
    members.sort_by_key(|m| m.id);
    (StatusCode::OK, Json(members)).into_response()
}

#[derive(Deserialize)]
pub struct UpdateMember {
    pub club_id: Option<u32>,
}

pub async fn update_member(
    State(state): State<Arc<AppState>>,
    Path(member_id): Path<u32>,
    Json(body): Json<UpdateMember>,
) -> impl IntoResponse {
    let mut store = state.store.lock().unwrap();
    if !store.members.contains_key(&member_id) {
        return (StatusCode::NOT_FOUND, Json(json!({"error": "member not found"}))).into_response();
    }
    if let Some(new_club_id) = body.club_id {
        let current_club_id = store.members.get(&member_id).unwrap().club_id;
        if new_club_id != current_club_id {
            if !store.clubs.contains_key(&new_club_id) {
                return (StatusCode::BAD_REQUEST, Json(json!({"error": "club_id must reference an existing club"}))).into_response();
            }
            if cap_exceeded(&store, new_club_id) {
                return (StatusCode::BAD_REQUEST, Json(json!({"error": "target club is at max_members capacity"}))).into_response();
            }
            store.members.get_mut(&member_id).unwrap().club_id = new_club_id;
        }
    }
    let member = store.members.get(&member_id).unwrap().clone();
    (StatusCode::OK, Json(member)).into_response()
}

